const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const roi = ee.Geometry.Point([-116.5453, 33.8303]).buffer(5000); // Palm Springs, CA
    const start = '2017-06-15T00:00:00';
    const end = '2017-06-22T00:00:00'; // exclusive end
    const threshK = 273.15 + (115 - 32) * 5 / 9; // 115°F in Kelvin (~319.26 K)

    // Helper to await getInfo
    const getInfo = (obj) => new Promise((resolve, reject) => obj.getInfo((v, e) => e ? reject(e) : resolve(v)));

    // 2. Data Acquisition & Check with fallback
    let datasetId = 'ECMWF/ERA5_LAND/HOURLY';
    let col = ee.ImageCollection(datasetId).filterDate(start, end).select('temperature_2m');
    let size = await getInfo(col.size());
    if (size === 0) {
      console.log('Primary images: 0');
      datasetId = 'ECMWF/ERA5/HOURLY';
      col = ee.ImageCollection(datasetId).filterDate(start, end).select('temperature_2m');
      size = await getInfo(col.size());
      if (size === 0) {
        console.log('Fallback images: 0');
        console.log('C1');
        return;
      } else {
        console.log(`Dataset: ERA5 Hourly (fallback), Images: ${size}`);
      }
    } else {
      console.log(`Dataset: ERA5-Land Hourly, Images: ${size}`);
    }

    // 3. Processing: per-hour mean over ROI + pixel count
    const annotate = function(img) {
      const mean = img.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: roi,
        scale: 9000,
        maxPixels: 1e9,
        bestEffort: true
      }).get('temperature_2m');
      const count = img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: 9000,
        maxPixels: 1e9,
        bestEffort: true
      }).get('temperature_2m');
      return img.set({t: mean, n: count});
    };
    const colAnn = col.map(annotate);
    const valid = colAnn.filter(ee.Filter.gt('n', 0));
    const nValid = await getInfo(valid.size());
    const sumN = await getInfo(valid.aggregate_sum('n'));
    if (nValid === 0 || sumN === 0) {
      console.log(`Valid hours (n>0): ${nValid}, Total pixel samples: ${sumN}`);
      console.log('C2');
      return;
    }
    console.log(`Valid hours (n>0): ${nValid}, Total pixel samples: ${sumN}, Mean pixels/hour: ${(sumN / nValid).toFixed(2)}`);

    // 4. Calculation: max, hours above threshold
    const maxT = await getInfo(valid.aggregate_max('t'));
    const maxImg = valid.sort('t', false).first();
    const maxTimeStr = await getInfo(ee.Date(maxImg.get('system:time_start')).format('YYYY-MM-dd HH:mm'));
    if (maxT === null || isNaN(maxT) || maxT < 200 || maxT > 350) {
      console.log(`Max temp invalid: ${maxT}`);
      console.log('C3');
      return;
    }
    const hoursAbove = await getInfo(valid.filter(ee.Filter.gte('t', threshK)).size());
    const pct = ((hoursAbove / nValid) * 100).toFixed(1);
    const c = maxT - 273.15;
    const f = c * 9 / 5 + 32;
    console.log(`Max temp: ${maxT.toFixed(2)} K = ${c.toFixed(2)} °C = ${f.toFixed(2)} °F at ${maxTimeStr} UTC`);
    console.log(`Hours ≥115°F: ${hoursAbove} / ${nValid} (${pct}%), Threshold: ${threshK.toFixed(2)} K`);

    // 5. Final Answer
    console.log(hoursAbove > 0 ? 'A' : 'B');
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
